const $=s=>document.querySelector(s);
const state={role:'learner',category:'All',query:'',mode:'All modes',saved:new Set(),enquiries:[],applications:[],requirements:[],services:[],profiles:{learner:{name:'',title:'',location:'',skills:'',bio:''},teacher:{name:'',title:'',location:'',skills:'',bio:''},institution:{name:'',title:'',location:'',skills:'',bio:''},training:{name:'',title:'',location:'',skills:'',bio:''}}};
const listings=[];
const jobs=[];
const talents=[];
const business=[];
const all=[...listings,...jobs,...talents,...business];
function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}
$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
const roleNames={learner:'Student / Parent',teacher:'Teacher / Expert',institution:'School / College',training:'Training Provider'};
function navigate(page){location.hash=page;if(location.hash==='#'+page)render()}
function changeRole(r){if(!Object.keys(roleNames).includes(r))throw new Error('Choose a supported role');state.role=r;state.query='';state.category='All';state.mode='All modes';$('#role').value=r;navigate(r==='learner'?'explore':'workspace')}
$('#role').onchange=e=>changeRole(e.target.value);
function side(page){const exploreLabel={learner:'Find learning',teacher:'Find teaching jobs',institution:'Discover teachers',training:'Business opportunities'}[state.role];const rows=[['explore','⌕',exploreLabel],['workspace','▦','My workspace'],['profile','◎','My profile'],['saved','♡','My shortlist'],['enquiries','↗','Messages & activity']];$('#side-nav').innerHTML=rows.map(([route,icon,label])=>`<a class="side-link ${page===route?'active':''}" href="#${route}"><span class="symbol">${icon}</span>${label}</a>`).join('');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('.avatar-btn').textContent=state.profiles[state.role].name.split(' ').slice(0,2).map(x=>x[0]).join('')}
function intro(k,h,p,b=''){return `<div class="intro"><div><span class="eyebrow">${k}</span><h1>${h}</h1><p class="muted">${p}</p></div>${b?`<span class="free-badge">${b}</span>`:''}</div>`}
function card(i){return `<article class="card"><div class="card-top"><span class="badge">${i.type}</span><button class="save ${state.saved.has(i.id)?'saved':''}" onclick="save(${i.id})" aria-label="${state.saved.has(i.id)?'Remove from':'Add to'} shortlist" aria-pressed="${state.saved.has(i.id)}">${state.saved.has(i.id)?'♥':'♡'}</button></div><div class="card-body"><div class="identity"><div class="initials ${i.color}">${i.initials}</div><div><h3>${i.name}</h3><small>${i.subtitle}</small></div></div><h3>${i.title}</h3><p class="desc">${i.desc}</p><div class="tags">${i.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="meta"><span>⌖ ${i.location}</span><span>◷ ${i.mode}</span></div></div><div class="card-foot"><div class="price">${i.price}<small>${i.note}</small></div><button class="btn light" onclick="detail(${i.id})">View ${i.id>100?'details':'profile'} ↗</button></div></article>`}
function save(id){if(state.saved.has(id))state.saved.delete(id);else state.saved.add(id);render();toast(state.saved.has(id)?'Added to your session shortlist':'Removed from shortlist')}
function detail(id){const i=all.find(x=>x.id===id);if(!i)return;modal(`<span class="eyebrow">${i.type.toUpperCase()}</span><h2>${i.title}</h2><p class="muted">${i.name} · ${i.location} · ${i.mode}</p><div class="tags">${i.tags.map(t=>`<span>${t}</span>`).join('')}</div><p class="muted">${i.details}</p><div class="panel"><strong>${i.price}</strong><p class="muted">${i.note}. ${i.id<100?'Talind discovery is free for students and parents. Provider fees are separate.':'Please verify listing details before proceeding.'}</p></div><div class="dialog-actions"><button class="btn" onclick="enquire(${id})">${id>=300?'Send proposal':id>=200?'Contact candidate':id>=100?'Apply for this job':i.type==='Schools / Colleges'?'Enquire about admission':'Request a demo / details'}</button><button class="btn outline" onclick="save(${id})">${state.saved.has(id)?'Remove from shortlist':'Shortlist'}</button></div>`)}
function enquire(id){$('#modal').close();const i=all.find(x=>x.id===id);modal(`<span class="eyebrow">${id>=100&&id<200?'APPLICATION':'ENQUIRY'}</span><h2>${i.name}</h2><p class="muted">Complete the details below. Messaging is not yet connected.</p><form id="enquiry-form"><div class="fields"><label class="full">Your name<input name="name" required maxlength="100" value="${esc(state.profiles[state.role].name)}"></label><label class="full">${id>=300?'Programme proposal':id>=100&&id<200?'Tell the institution about your experience':'What are you looking for?'}<textarea name="message" required maxlength="1500" placeholder="Share your goals, preferred timing and expectations."></textarea></label><label class="full">Preferred mode<select name="mode"><option>Online</option><option>In person</option><option>Hybrid</option></select></label></div><button class="btn" type="submit">${id>=100&&id<200?'Save application':'Save enquiry'}</button></form>`);$('#enquiry-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);const entry={role:state.role,target:i.name,title:i.title,message:d.get('message'),mode:d.get('mode')};if(id>=100&&id<200)state.applications.push(entry);else state.enquiries.push(entry);$('#modal').close();navigate('enquiries');toast('Saved for this session. No message was sent.')}}
function explore(){const learner=state.role==='learner';const cfg={learner:['YOUR NEXT CHAPTER','Find the right guidance.','Tuition, skills, coaching or a new institution. Start with what matters to you.','Free for students & parents'],teacher:['YOUR TALENT, MORE POSSIBILITIES','Find work that fits your skills.','Explore teaching roles and opportunities beyond the classroom.','Job seeking is free'],institution:['BUILD YOUR TEACHING TEAM','Find the skills your students need.','Explore teacher profiles and create a clear hiring requirement.','Paid institution membership'],training:['GROW YOUR TRAINING BUSINESS','Bring your expertise to institutions.','Discover workshop and training requirements from schools and colleges.','Paid provider membership']}[state.role];const cats=learner?['All','Tuition','Skill development','NEET / JEE','Schools / Colleges']:['All'];$('#main').innerHTML=intro(...cfg)+`<form class="searchbar" id="search-form"><input id="query" aria-label="Search by subject, skill or location" placeholder="${learner?'What would you like to learn?':'Search skills, roles or locations'}" value="${esc(state.query)}"><select id="mode" aria-label="Learning or working mode">${['All modes','Online','In person','Hybrid'].map(x=>`<option ${state.mode===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn">Search <span>↗</span></button></form><div class="tabs">${cats.map(c=>`<button class="chip ${state.category===c?'active':''}" data-cat="${c}">${c}</button>`).join('')}</div>${learner?`<div class="feature-band"><div><span class="tiny">YOUR GOAL COMES FIRST</span><h2>A good match starts with you.</h2><p>Tell us the subject, budget and schedule you have in mind.</p></div><button class="btn lime" onclick="requirement()">Post my learning need ↗</button></div>`:''}<div class="section-top"><div><h2>${learner?'Explore your possibilities':'Suggested opportunities'}</h2><p>${learner?'A few starting points for your next step.':'Published opportunities will appear here as they become available.'}</p></div><span class="count" id="result-count"></span></div><div class="cards" id="results"></div><p class="bottom-note">Only published profiles and opportunities will appear here.</p>`;$('#search-form').onsubmit=e=>{e.preventDefault();state.query=$('#query').value;state.mode=$('#mode').value;results()};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.cat;explore()});results()}
function results(){const src={learner:listings,teacher:jobs,institution:talents,training:business}[state.role];const q=state.query.toLowerCase().trim();const items=src.filter(i=>(state.category==='All'||i.type===state.category)&&(state.mode==='All modes'||i.mode===state.mode)&&(!q||[i.name,i.title,i.subtitle,i.desc,i.location,...i.tags].join(' ').toLowerCase().includes(q)));$('#result-count').textContent=items.length+' results';$('#results').innerHTML=items.length?items.map(card).join(''):'<div class="empty"><h3>No matches yet</h3><p class="muted">Try a broader subject, another location or all modes.</p><button class="btn light" onclick="resetSearch()">Clear filters</button></div>'}
function resetSearch(){state.query='';state.mode='All modes';state.category='All';explore()}
function requirement(){modal(`<span class="eyebrow">${state.role==='learner'?'LEARNING':'INSTITUTIONAL'} REQUIREMENT</span><h2>Tell us what you need.</h2><p class="muted">Create your requirement.</p><form id="requirement-form"><div class="fields"><label class="full">Requirement title<input name="title" required maxlength="120" placeholder="e.g. Class 10 Maths tuition or teacher training"></label><label>Location<input name="location" required placeholder="City or online"></label><label>Budget<input name="budget" required placeholder="e.g. ₹2,000 / month"></label><label>Preferred mode<select name="mode"><option>Online</option><option>In person</option><option>Hybrid</option></select></label><label>Timing<input name="timing" required placeholder="e.g. Weekday evenings"></label><label class="full">Skills, goals and expectations<textarea name="details" required maxlength="1500"></textarea></label></div><button class="btn">Save requirement</button></form>`);$('#requirement-form').onsubmit=e=>{e.preventDefault();state.requirements.push({...Object.fromEntries(new FormData(e.target)),role:state.role});$('#modal').close();navigate('workspace');toast('Requirement saved for this session. Cloud publishing is coming next.')}}
function service(){modal(`<span class="eyebrow">PAID SERVICE LISTING</span><h2>${state.role==='teacher'?'Offer your expertise.':'Create a learning programme.'}</h2><p class="muted">Create your service or programme listing. Online payment is not yet enabled.</p><form id="service-form"><div class="fields"><label class="full">Service or programme name<input name="title" required maxlength="120" placeholder="e.g. Weekend Maths coaching"></label><label>Fee<input name="fee" required placeholder="₹500 / session"></label><label>Audience<input name="audience" required placeholder="Classes 8–10 / adult learners"></label><label class="full">What will participants learn?<textarea name="details" required maxlength="1500"></textarea></label></div><button class="btn">Save service</button></form>`);$('#service-form').onsubmit=e=>{e.preventDefault();state.services.push({...Object.fromEntries(new FormData(e.target)),role:state.role});$('#modal').close();navigate('workspace');toast('Service draft saved for this session. Cloud publishing is coming next.')}}
function workspace(){const r=state.role,p=state.profiles[r],en=state.enquiries.filter(x=>x.role===r),req=state.requirements.filter(x=>x.role===r),sv=state.services.filter(x=>x.role===r);const copy={learner:['Your learning, your way.','Keep your learning goals, enquiries and favourite profiles together.'],teacher:['One profile. More possibilities.','Find your next teaching job and build an independent coaching practice.'],institution:['Your institution, connected.','Build your teaching team and help families discover your institution.'],training:['Grow your reach.','Bring programmes to individual learners and training solutions to institutions.']}[r];$('#main').innerHTML=intro('MY WORKSPACE',copy[0],copy[1],r==='learner'?'Completely free access':r==='teacher'?'Free job seeking · Paid services':'Paid membership')+`<div class="stats"><div class="stat"><b>${state.saved.size}</b><span>Shortlisted profiles</span></div><div class="stat"><b>${en.length+state.applications.filter(x=>x.role===r).length}</b><span>Enquiries / applications</span></div><div class="stat"><b>${req.length+sv.length}</b><span>Your listings</span></div></div><div class="split"><section class="panel"><span class="eyebrow">${r==='learner'?'YOUR LEARNING':r==='teacher'?'01 / FIND A JOB':r==='institution'?'01 / HIRE TEACHERS':'01 / REACH LEARNERS'}</span><h2 style="margin-top:12px">${r==='learner'?'Find the right support':r==='teacher'?'Let your skills find their place':r==='institution'?'Build a strong teaching team':'Turn expertise into learning'}</h2><p class="muted">${r==='learner'?'Compare tutors and programmes, then tell providers what you need.':r==='teacher'?'Keep your professional profile ready and explore relevant teaching roles for free.':r==='institution'?'Define the role, curriculum and skills you need. Review candidate profiles.':'Create programmes for students, teachers and anybody looking to develop a skill.'}</p><div class="workspace-links"><button class="btn" onclick="${r==='training'?'service()':"navigate('explore')"}">${r==='training'?'Add a programme':r==='institution'?'Discover teachers':r==='teacher'?'Explore jobs':'Explore learning'}</button><button class="btn outline" onclick="${r==='institution'||r==='learner'?'requirement()':"navigate('profile')"}">${r==='institution'?'Post a requirement':r==='learner'?'Post my need':'Edit profile'}</button></div></section><section class="panel"><span class="eyebrow">${r==='learner'?'YOUR EXPECTATIONS':r==='teacher'?'02 / OFFER SERVICES':r==='institution'?'02 / REACH FAMILIES':'02 / WORK WITH INSTITUTIONS'}</span><h2 style="margin-top:12px">${r==='learner'?'A profile built around your goals':r==='teacher'?'Teach beyond the classroom':r==='institution'?'Help parents discover you':'Create larger opportunities'}</h2><p class="muted">${r==='learner'?'Share subjects, location and learning preferences. Your access to Talind stays free.':r==='teacher'?'Offer tuition, online coaching or workshops through a paid service-provider membership.':r==='institution'?'Showcase programmes and facilities, and manage admission enquiries.':'Respond to training requirements and propose workshops for schools and colleges.'}</p><button class="btn light" onclick="${r==='teacher'?'service()':r==='training'?"navigate('explore')":"navigate('profile')"}">${r==='teacher'?'Create a service':r==='training'?'Find business opportunities':'Manage profile'} ↗</button></section></div><section class="panel"><div class="section-top"><h2>Your listings</h2><span class="count">Saved to Talind</span></div>${req.length+sv.length?[...req,...sv].map(x=>`<div class="row"><div><strong>${esc(x.title)}</strong><p>${esc(x.budget||x.fee)} · ${esc(x.location||x.audience)}</p></div><span class="badge">Draft</span></div>`).join(''):'<p class="muted">Your requirements and service drafts will appear here. Try the actions above.</p>'}</section>`}
function profile(){const p=state.profiles[state.role];$('#main').innerHTML=intro('MY PROFILE','Make the right introduction.','Your profile helps people understand your skills, goals and expectations.')+`<section class="panel"><div class="profile-header"><div class="initials green">${esc(p.name.split(' ').slice(0,2).map(s=>s[0]).join(''))}</div><div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.title)}</p><span class="badge">Profile · ${roleNames[state.role]}</span></div></div><form id="profile-form"><div class="fields"><label>Name / organisation<input name="name" required maxlength="100" value="${esc(p.name)}"></label><label>Location<input name="location" required maxlength="100" value="${esc(p.location)}"></label><label class="full">Profile headline<input name="title" required maxlength="150" value="${esc(p.title)}"></label><label class="full">${state.role==='learner'?'Learning interests':'Skills / programmes / strengths'}<input name="skills" required maxlength="300" value="${esc(p.skills)}"></label><label class="full">About / expectations<textarea name="bio" maxlength="1500">${esc(p.bio)}</textarea></label></div><button class="btn">Save profile</button><p class="bottom-note">Your saved profile is linked to your Talind account when signed in.</p></form></section>`;$('#profile-form').onsubmit=e=>{e.preventDefault();state.profiles[state.role]=Object.fromEntries(new FormData(e.target));render();toast('Profile updated')}}
function saved(){const items=all.filter(i=>state.saved.has(i.id));$('#main').innerHTML=intro('MY SHORTLIST','Keep your possibilities close.','Review your saved profiles and compare the details that matter.')+`<div class="section-top"><span class="count">${items.length} saved</span>${items.length>1?'<button class="btn outline" onclick="compare()">Compare shortlist</button>':''}</div><div class="cards">${items.length?items.map(card).join(''):'<div class="empty"><h3>Your shortlist is waiting</h3><p class="muted">Tap the heart on a profile to save it here.</p><a class="btn" href="#explore">Explore profiles</a></div>'}</div>`}
function compare(){const items=all.filter(i=>state.saved.has(i.id));modal(`<span class="eyebrow">YOUR SHORTLIST</span><h2>Compare your options</h2><div class="comparison"><table><thead><tr><th>Detail</th>${items.map(i=>`<th>${i.name}</th>`).join('')}</tr></thead><tbody>${[['Type','type'],['Location','location'],['Mode','mode'],['Indicative fee / salary','price']].map(([label,key])=>`<tr><th>${label}</th>${items.map(i=>`<td>${i[key]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="bottom-note">Compare shortlisted profiles and opportunities after real listings are available.</p>`)}
function activity(){const entries=[...state.enquiries,...state.applications].filter(x=>x.role===state.role);$('#main').innerHTML=intro('ENQUIRIES & ACTIVITY','Your conversations start here.','Review your enquiries and applications.')+`<section class="panel">${entries.length?entries.map(x=>`<div class="row"><div><strong>${esc(x.target)}</strong><p>${esc(x.title)} · ${esc(x.mode)}</p><p>${esc(x.message)}</p></div><span class="badge">Saved</span></div>`).join(''):'<div class="empty"><h3>No activity yet</h3><p class="muted">Open a profile and try an enquiry or application.</p><a class="btn" href="#explore">Explore</a></div>'}</section><p class="bottom-note">Direct messaging is not yet enabled.</p>`}
function plans(){$('#main').innerHTML=intro('MEMBERSHIP','Free to discover. Built to grow.','Clear access for every part of the Talind community.')+`<div class="cards"><article class="card plan recommended"><span class="eyebrow">STUDENTS & PARENTS</span><h3>Find your next step</h3><div class="plan-price">Completely free</div><ul><li>Discover tutors and coaching</li><li>Explore skill-development courses</li><li>Compare schools and colleges</li><li>Shortlist and send enquiries</li></ul><button class="btn" onclick="changeRole('learner')">Try learner experience</button></article><article class="card plan"><span class="eyebrow">TEACHERS & EXPERTS</span><h3>Work & opportunity</h3><div class="plan-price">Jobs: Free · Services: Paid</div><ul><li>Seek and apply for teaching/faculty jobs — free</li><li>Use your profile for employment opportunities — free</li><li>Offer tuition, coaching, mentoring or workshops — paid membership</li><li>Match with learners, quote and provide services — paid membership</li></ul><button class="btn light" onclick="changeRole('teacher')">Try teacher experience</button></article><article class="card plan"><span class="eyebrow">SCHOOLS & COLLEGES</span><h3>Hire & be discovered</h3><div class="plan-price">Paid membership</div><ul><li>Find teachers with relevant skills</li><li>Post staffing requirements</li><li>Showcase programmes and facilities</li><li>Receive admission enquiries</li></ul><button class="btn light" onclick="changeRole('institution')">Try institution experience</button></article><article class="card plan"><span class="eyebrow">TRAINING PROVIDERS</span><h3>Reach & expand</h3><div class="plan-price">Paid membership</div><ul><li>Offer courses to individual learners</li><li>Promote skill-development programmes</li><li>Find institutional training needs</li><li>Send workshop proposals</li></ul><button class="btn light" onclick="changeRole('training')">Try provider experience</button></article></div><section class="panel"><h2>A simple distinction</h2><p class="muted">Students and parents use Talind for free. Teachers use Talind free only for job seeking; providing tuition, coaching, mentoring, workshops or other services requires a paid Teacher Services membership. Provider service fees are separate. Subscription prices for paid accounts are still to be decided. Online payments are not yet enabled.</p></section>`}
function render(){const page=location.hash.slice(1)||'explore';side(page);({explore,workspace,profile,saved,enquiries:activity,plans}[page]||explore)();$('#main').insertAdjacentHTML('beforeend','<footer>talind · Skills. Opportunities. Growth. <button class="text-button" onclick="talindSafetyGuide()">Safety & professional conduct</button></footer>')}
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_talind_role',description:'Switch the visible Talind experience to a learner, teacher, institution or training provider.',inputSchema:{type:'object',properties:{role:{type:'string',enum:['learner','teacher','institution','training']}},required:['role'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({role})=>{changeRole(role);return{role:state.role,page:location.hash.slice(1)}}})).catch(()=>{});}catch(e){}}
